def act(step, user):
    # layer 1: only known tools
    if step.tool not in ALLOWED_TOOLS:
        return "blocked: unknown tool"
    # layer 2: least privilege (scoped, read-only where possible)
    # layer 3: human approval for irreversible actions
    if step.tool in HIGH_RISK and not user.approved(step):
        return "awaiting human approval"
    return run_tool(step.tool, step.args)   # + log every call
